CREATE TYPE "UserRole" AS ENUM ('ADMIN', 'LEADER', 'MEMBER');
CREATE TYPE "AttendanceStatus" AS ENUM ('PRESENT', 'LATE', 'ABSENT', 'EXCUSED');
CREATE TYPE "ScheduleType" AS ENUM ('WORSHIP', 'TRAINING', 'EVENT');
CREATE TYPE "SlideType" AS ENUM ('LYRICS', 'SCRIPTURE', 'ANNOUNCEMENT', 'TEXT');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "role" "UserRole" NOT NULL DEFAULT 'MEMBER', "emailVerifiedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "EmailVerification" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "codeHash" TEXT NOT NULL, "purpose" TEXT NOT NULL DEFAULT 'VERIFY_EMAIL', "expiresAt" TIMESTAMP(3) NOT NULL, "consumedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EmailVerification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "ChurchConfig" ("id" TEXT PRIMARY KEY DEFAULT 'main', "name" TEXT NOT NULL DEFAULT 'Cornerstone Global Harvest Church', "logoUrl" TEXT, "service1Start" TEXT NOT NULL DEFAULT '08:00', "service1End" TEXT NOT NULL DEFAULT '10:00', "service2Start" TEXT NOT NULL DEFAULT '10:00', "service2End" TEXT NOT NULL DEFAULT '12:00', "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Ministry" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL UNIQUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Member" ("id" TEXT PRIMARY KEY, "userId" TEXT UNIQUE, "ministryId" TEXT, "firstName" TEXT NOT NULL, "lastName" TEXT NOT NULL, "age" INTEGER, "photoUrl" TEXT, "instrument" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Member_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT "Member_ministryId_fkey" FOREIGN KEY ("ministryId") REFERENCES "Ministry"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "Song" ("id" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "artist" TEXT, "originalKey" TEXT, "teamKey" TEXT, "bpm" INTEGER, "worshipLeader" TEXT, "youtubeUrl" TEXT, "chordText" TEXT, "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "SongMusician" ("id" TEXT PRIMARY KEY, "songId" TEXT NOT NULL, "memberId" TEXT NOT NULL, "role" TEXT NOT NULL, CONSTRAINT "SongMusician_songId_fkey" FOREIGN KEY ("songId") REFERENCES "Song"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SongMusician_memberId_fkey" FOREIGN KEY ("memberId") REFERENCES "Member"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "ChordFile" ("id" TEXT PRIMARY KEY, "songId" TEXT NOT NULL, "fileName" TEXT NOT NULL, "filePath" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "size" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ChordFile_songId_fkey" FOREIGN KEY ("songId") REFERENCES "Song"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Schedule" ("id" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "type" "ScheduleType" NOT NULL, "startsAt" TIMESTAMP(3) NOT NULL, "endsAt" TIMESTAMP(3), "location" TEXT, "details" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Service" ("id" TEXT PRIMARY KEY, "scheduleId" TEXT NOT NULL, "name" TEXT NOT NULL, "startsAt" TIMESTAMP(3) NOT NULL, "endsAt" TIMESTAMP(3), CONSTRAINT "Service_scheduleId_fkey" FOREIGN KEY ("scheduleId") REFERENCES "Schedule"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "ServiceAssignment" ("id" TEXT PRIMARY KEY, "serviceId" TEXT NOT NULL, "memberId" TEXT NOT NULL, "role" TEXT NOT NULL, "slot" INTEGER NOT NULL DEFAULT 1, CONSTRAINT "ServiceAssignment_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "Service"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "ServiceAssignment_memberId_fkey" FOREIGN KEY ("memberId") REFERENCES "Member"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Training" ("id" TEXT PRIMARY KEY, "scheduleId" TEXT NOT NULL UNIQUE, "ministryId" TEXT, "description" TEXT, CONSTRAINT "Training_scheduleId_fkey" FOREIGN KEY ("scheduleId") REFERENCES "Schedule"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "Training_ministryId_fkey" FOREIGN KEY ("ministryId") REFERENCES "Ministry"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "Attendance" ("id" TEXT PRIMARY KEY, "trainingId" TEXT NOT NULL, "memberId" TEXT NOT NULL, "status" "AttendanceStatus" NOT NULL, "notes" TEXT, "markedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Attendance_trainingId_fkey" FOREIGN KEY ("trainingId") REFERENCES "Training"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "Attendance_memberId_fkey" FOREIGN KEY ("memberId") REFERENCES "Member"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Presentation" ("id" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Slide" ("id" TEXT PRIMARY KEY, "presentationId" TEXT NOT NULL, "position" INTEGER NOT NULL, "type" "SlideType" NOT NULL DEFAULT 'TEXT', "text" TEXT, "background" TEXT, "backgroundUrl" TEXT, "fontFamily" TEXT, "fontSize" INTEGER, "textColor" TEXT, "alignment" TEXT, CONSTRAINT "Slide_presentationId_fkey" FOREIGN KEY ("presentationId") REFERENCES "Presentation"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "LinkResource" ("id" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "url" TEXT NOT NULL, "addedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY, "userId" TEXT, "action" TEXT NOT NULL, "module" TEXT NOT NULL, "recordId" TEXT, "beforeJson" JSONB, "afterJson" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "EmailVerification_userId_purpose_expiresAt_idx" ON "EmailVerification"("userId", "purpose", "expiresAt");
CREATE INDEX "Song_title_idx" ON "Song"("title"); CREATE INDEX "Song_artist_idx" ON "Song"("artist");
CREATE UNIQUE INDEX "SongMusician_songId_memberId_role_key" ON "SongMusician"("songId", "memberId", "role");
CREATE INDEX "Schedule_type_startsAt_idx" ON "Schedule"("type", "startsAt");
CREATE UNIQUE INDEX "ServiceAssignment_serviceId_memberId_key" ON "ServiceAssignment"("serviceId", "memberId"); CREATE INDEX "ServiceAssignment_memberId_idx" ON "ServiceAssignment"("memberId");
CREATE INDEX "Attendance_memberId_markedAt_idx" ON "Attendance"("memberId", "markedAt"); CREATE UNIQUE INDEX "Attendance_trainingId_memberId_key" ON "Attendance"("trainingId", "memberId");
CREATE UNIQUE INDEX "Slide_presentationId_position_key" ON "Slide"("presentationId", "position");
CREATE INDEX "AuditLog_userId_createdAt_idx" ON "AuditLog"("userId", "createdAt"); CREATE INDEX "AuditLog_module_action_createdAt_idx" ON "AuditLog"("module", "action", "createdAt");
